<template>
 <section class="staffing-board" aria-label="School waitlists and staffing">
  <header><div><h2>School waitlists &amp; staffing</h2><p>See where additional school care is needed and the insurance recorded for those waitlists.</p></div><button type="button" :disabled="loading" @click="load">{{loading?'Refreshing…':'Refresh'}}</button></header>
  <p v-if="error" role="alert">{{error}}</p><p v-if="loading" role="status">Loading school demand…</p>
  <div class="staffing-stats"><div><strong>{{summary.schoolsWithWaitlists||0}}</strong><span>Schools with waitlists</span></div><div><strong>{{summary.waitlistEntries||0}}</strong><span>Waitlist entries</span></div><div><strong>{{summary.openPostings||0}}</strong><span>Open staffing posts</span></div></div>
  <p class="staffing-boundary">Counts and staffing requirements are shared here. Individual student records remain in their authorized school portals. Insurance and actual working hours need confirmation before placement.</p>
  <div v-if="schools.length" class="staffing-table"><table><thead><tr><th>School</th><th>Students waitlisted</th><th>Insurance recorded</th><th>Staffing requirements</th><th v-if="canPost">Manage</th></tr></thead><tbody>
   <tr v-for="school in schools" :key="school.schoolId"><th scope="row">{{school.schoolName}}</th><td>{{school.waitlistCount}}</td><td><ul><li v-for="insurance in school.insuranceMix" :key="insurance.name">{{insurance.name}} · {{insurance.count}}</li></ul><span v-if="!school.insuranceMix.length">No current waitlist</span></td><td><article v-for="need in school.staffingNeeds" :key="need.id"><strong>{{need.title||'Additional provider needed'}}</strong><p v-if="need.days.length">{{need.days.join(', ')}} · {{need.slotsNeeded}} client spots</p><p v-if="need.notes">{{need.notes}}</p><button v-if="canPost" type="button" :disabled="saving" @click="closePosting(need)">Close posting</button></article><p v-if="!school.staffingNeeds.length">Requirements have not been posted.</p></td><td v-if="canPost"><button type="button" @click="startPosting(school)">Add staffing note</button></td></tr>
  </tbody></table></div><p v-else-if="!loading&&!error">No current school waitlists or open staffing posts.</p>
  <form v-if="draft" class="staffing-form" @submit.prevent="post"><h3>Post a school need · {{draft.schoolName}}</h3><p>Providers can see these staffing requirements and request the existing school placement. Keep student names and private clinical details in the school record.</p>
   <label>Title<input v-model.trim="draft.title" maxlength="255" placeholder="Licensed provider or trauma training needed" /></label><label>Client spots needed<input v-model.number="draft.slotsNeeded" type="number" min="1" max="50" required /></label>
   <fieldset><legend>Preferred weekdays</legend><label v-for="day in weekdays" :key="day"><input v-model="draft.days" type="checkbox" :value="day" />{{day}}</label></fieldset>
   <label>Staffing notes<textarea v-model.trim="draft.body" rows="3" maxlength="2000" required placeholder="License, training, insurance, start date, or day requirements" /></label>
   <div><button type="submit" :disabled="saving">{{saving?'Posting…':'Post school need'}}</button><button type="button" :disabled="saving" @click="draft=null">Cancel</button></div>
  </form>
  <details v-if="canRequest" @toggle="placementsOpen=$event.target.open"><summary>Request a posted school placement</summary><ProviderYearUpdateSchoolNeedsPanel v-if="placementsOpen" :agency-id="agencyId" :school-year="schoolYear" /></details>
  <p v-if="notice" role="status">{{notice}}</p>
 </section>
</template>
<script setup>
import {computed,ref,watch} from 'vue';
import api from '../../services/api';
import {useAuthStore} from '../../store/auth';
import {currentSchoolYear} from '../../utils/schoolReinit';
import ProviderYearUpdateSchoolNeedsPanel from '../provider/ProviderYearUpdateSchoolNeedsPanel.vue';
const props=defineProps({agencyId:{type:Number,required:true},allowManagement:{type:Boolean,default:true}});
const auth=useAuthStore(),schools=ref([]),summary=ref({}),loading=ref(false),saving=ref(false),error=ref(''),notice=ref(''),draft=ref(null),placementsOpen=ref(false);
const schoolYear=currentSchoolYear(),weekdays=['Monday','Tuesday','Wednesday','Thursday','Friday'];
const canPost=computed(()=>props.allowManagement&&['admin','super_admin','support'].includes(auth.user?.role));
const canRequest=computed(()=>['provider','provider_plus','intern','intern_plus','supervisor','clinical_practice_assistant'].includes(auth.user?.role));
let version=0,scope=0;
async function load(){const request=++version;loading.value=true;error.value='';try{const {data}=await api.get('/school-coverage/waitlists',{params:{agencyId:props.agencyId,schoolYear},skipGlobalLoading:true});if(request===version){schools.value=data.schools||[];summary.value=data.summary||{};}}catch(e){if(request===version)error.value=e.response?.data?.error?.message||'School staffing could not be loaded.';}finally{if(request===version)loading.value=false;}}
function startPosting(school){draft.value={schoolOrganizationId:school.schoolId,schoolName:school.schoolName,title:'',body:'',days:[],slotsNeeded:Math.max(1,Math.min(50,school.waitlistCount||1))};notice.value='';}
async function post(){if(!canPost.value||saving.value||!draft.value)return;const requestScope=scope;saving.value=true;error.value='';try{await api.post('/provider-year-update/school-needs',{agencyId:props.agencyId,schoolYear,...draft.value});if(requestScope!==scope)return;draft.value=null;notice.value='School need posted for the agency’s providers.';await load();}catch(e){if(requestScope===scope)error.value=e.response?.data?.error?.message||'The school need could not be posted.';}finally{saving.value=false;}}
async function closePosting(need){if(!canPost.value||saving.value)return;const requestScope=scope;saving.value=true;error.value='';try{await api.patch(`/provider-year-update/school-needs/${need.id}`,{agencyId:props.agencyId,status:'closed'});if(requestScope!==scope)return;notice.value='Staffing post closed.';await load();}catch(e){if(requestScope===scope)error.value=e.response?.data?.error?.message||'The staffing post could not be closed.';}finally{saving.value=false;}}
watch(()=>props.agencyId,()=>{++scope;++version;schools.value=[];summary.value={};draft.value=null;placementsOpen.value=false;notice.value='';if(props.agencyId)load();},{immediate:true});
</script>
<style scoped>
.staffing-board{padding:22px;background:#fff;border:1px solid #dce5df;border-radius:12px;color:#203e36}.staffing-board header{display:flex;justify-content:space-between;gap:18px;align-items:start}.staffing-board h2,.staffing-board h3{margin:0 0 8px}.staffing-board p{line-height:1.55}.staffing-stats{display:flex;gap:16px;flex-wrap:wrap;margin:20px 0}.staffing-stats>div{display:grid;gap:4px;min-width:140px;padding:14px 18px;border:1px solid #dce7df;border-radius:10px;background:#f4f9f5}.staffing-stats strong{font-size:24px}.staffing-stats span,.staffing-boundary{font-size:13px;color:#5d7368}.staffing-table{overflow:auto}table{width:100%;border-collapse:collapse;text-align:left}th,td{padding:14px 12px;border-bottom:1px solid #dce5df;vertical-align:top}thead{background:#f0f6f2}ul{padding-left:16px;margin:0;line-height:1.65}article+article{margin-top:14px;padding-top:12px;border-top:1px solid #dce5df}article p{margin:5px 0}.staffing-board button{padding:8px 12px;border:1px solid #b4cabd;background:#f7fbf8;border-radius:7px;color:#166534;cursor:pointer;font:inherit}.staffing-board button:disabled{opacity:.6}.staffing-form{display:grid;gap:14px;margin-top:20px;padding:20px;border:1px solid #b9d1c0;border-radius:10px;background:#f6faf7}.staffing-form>label{display:grid;gap:7px}.staffing-form input:not([type=checkbox]),textarea{padding:9px;border:1px solid #b9cbbf;border-radius:6px;font:inherit}.staffing-form fieldset{display:flex;flex-wrap:wrap;gap:14px;border:1px solid #c8d8ce}.staffing-form>div{display:flex;gap:10px}.staffing-board details{margin-top:20px}.staffing-board summary{cursor:pointer;font-weight:600}[role=alert]{color:#a32129}@media(max-width:600px){.staffing-board{padding:14px}.staffing-board header{flex-direction:column}.staffing-stats{gap:9px}.staffing-stats>div{min-width:110px;padding:10px}th,td{padding:10px}}
</style>
